insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$rio-claro$q$, $q$https://data.queridodiario.ok.org.br/3543907/2021-12-22/9f31122e169cd4dfebb66bb53ce87c57bed6a06e.pdf (DOM ed. 1299, Dec. 12.448/2021) ; https://data.queridodiario.ok.org.br/3543907/2019-11-14/2bb14a0d3b050dda9758d0fe8f54e1a0e042ba0e.pdf (PlanMob, DOM 1028) ; https://data.queridodiario.ok.org.br/3543907/2019-05-03/7c94e73df88862347073ee1176259aba94c1fbbd.pdf (Dec. 11.440/2019)$q$, $q$Atos oficiais de Rio Claro: domínio público (Lei 9.610/1998 art. 8º IV). Geometria das vias: OpenStreetMap (ODbL 1.0, © colaboradores do OSM). Registro revogado: limite municipal do IBGE.$q$, 20, $q$Regra ativa: Dec. 12.448/2021, art. 1º, PBT acima de 3 t proibido em 9 vias do centro (Ruas 2 a 5 entre as Avs. 5 e 6; Rua 6 entre as Avs. 2 e 3; Avs. 1 a 4 entre as Ruas 1 e 8), 2ª a 6ª 9h–18h e sábado 9h–15h, sem exceção de feriado. As Leis 2.787/1995 e 3.480/2004 não puderam ser lidas (só o resumo do PlanMob): desativadas. Restrições só com notícia (16 t no Jd. Itapuã; ponte de madeira da Av. 14) e carga e descarga (Dec. 11.440/2019): desativadas, sem geometria.$q$);
